CREATE   PROCEDURE [dbo].[UspPBIMonVolumeFluxo] @fluxo_codigo VARCHAR(50), @cli_cd_codigo_cliente INT = NULL, @data_inicio DATE = NULL, @data_fim DATE = NULL AS BEGIN SET NOCOUNT ON; IF @fluxo_codigo IS NULL BEGIN RAISERROR('@fluxo_codigo e obrigatorio.', 16, 1); RETURN; END IF @data_inicio IS NULL AND @data_fim IS NULL BEGIN RAISERROR('Informe @data_inicio e/ou @data_fim.', 16, 1); RETURN; END SET @data_inicio = ISNULL(@data_inicio, @data_fim); SET @data_fim = ISNULL(@data_fim, @data_inicio); IF @data_inicio > @data_fim BEGIN RAISERROR('@data_inicio nao pode ser maior que @data_fim.', 16, 1); RETURN; END DECLARE @v_fluxo_id INT; DECLARE @v_fluxo_codigo VARCHAR(50); DECLARE @v_fluxo_nome NVARCHAR(200); DECLARE @v_processo_id INT; SELECT @v_fluxo_id = f.fluxo_id, @v_fluxo_codigo = f.fluxo_codigo, @v_fluxo_nome = f.fluxo_nome, @v_processo_id = f.processo_id FROM dbo.tb_pbi_mon_fluxos f WITH (NOLOCK) WHERE f.fluxo_ativo = 1 AND f.fluxo_codigo = @fluxo_codigo; IF @v_fluxo_id IS NULL BEGIN RAISERROR('Fluxo nao encontrado ou inativo.', 16, 1); RETURN; END CREATE TABLE #Clientes (cli_cd_codigo_cliente INT, id_transportadora INT, nm_transportadora NVARCHAR(50), alerta_fato_id BIGINT NULL); IF @cli_cd_codigo_cliente IS NOT NULL BEGIN INSERT INTO #Clientes (cli_cd_codigo_cliente, id_transportadora, nm_transportadora, alerta_fato_id) SELECT TOP 1 a.cli_cd_codigo_cliente, a.id_transportadora, a.nm_transportadora, a.alerta_fato_id FROM dbo.tb_pbi_mon_alertas_fato a WITH (NOLOCK) WHERE a.in_dashboard_alarmes_habilitado = 1 AND a.cli_cd_codigo_cliente = @cli_cd_codigo_cliente AND (a.processo_codigo = @v_fluxo_codigo OR (@v_processo_id IS NOT NULL AND a.processo_id = @v_processo_id)) ORDER BY a.dh_atualizacao DESC; IF NOT EXISTS (SELECT 1 FROM #Clientes) BEGIN INSERT INTO #Clientes (cli_cd_codigo_cliente, id_transportadora, nm_transportadora, alerta_fato_id) SELECT TOP 1 c.cli_cd_codigo_cliente, c.cli_id_logistics, c.cli_ds_nome, NULL FROM dbo.tb_clientes c WITH (NOLOCK) WHERE c.cli_cd_codigo_cliente = @cli_cd_codigo_cliente AND c.cli_in_ativo = 1; END END ELSE BEGIN INSERT INTO #Clientes (cli_cd_codigo_cliente, id_transportadora, nm_transportadora, alerta_fato_id) SELECT a.cli_cd_codigo_cliente, MAX(a.id_transportadora), MAX(a.nm_transportadora), MAX(a.alerta_fato_id) FROM dbo.tb_pbi_mon_alertas_fato a WITH (NOLOCK) WHERE a.in_dashboard_alarmes_habilitado = 1 AND (a.processo_codigo = @v_fluxo_codigo OR (@v_processo_id IS NOT NULL AND a.processo_id = @v_processo_id)) GROUP BY a.cli_cd_codigo_cliente; END IF NOT EXISTS (SELECT 1 FROM #Clientes) BEGIN RAISERROR('Nenhum cliente ativo encontrado para o fluxo.', 16, 1); RETURN; END CREATE TABLE #Resultado (cli_cd_codigo_cliente INT, id_transportadora INT, nm_transportadora NVARCHAR(50), alerta_fato_id BIGINT NULL, dt_referencia DATE NULL, fluxo_id INT, fluxo_codigo VARCHAR(50), fluxo_nome NVARCHAR(200), etapa_id INT, etapa_ordem INT, etapa_nome NVARCHAR(200), volume BIGINT, data_inicio DATE, data_fim DATE); DECLARE @cliente_cli_cd INT; DECLARE @cliente_id_transp INT; DECLARE @cliente_nm NVARCHAR(50); DECLARE @cliente_alerta_id BIGINT; DECLARE @cliente_data_inicio DATE; DECLARE @cliente_data_fim DATE; SET @cliente_data_inicio = @data_inicio; SET @cliente_data_fim = @data_fim; DECLARE cur_cli CURSOR LOCAL FAST_FORWARD FOR SELECT cli_cd_codigo_cliente, id_transportadora, nm_transportadora, alerta_fato_id FROM #Clientes ORDER BY cli_cd_codigo_cliente; OPEN cur_cli; FETCH NEXT FROM cur_cli INTO @cliente_cli_cd, @cliente_id_transp, @cliente_nm, @cliente_alerta_id; WHILE @@FETCH_STATUS = 0 BEGIN DECLARE @etapa_id INT; DECLARE @etapa_ordem INT; DECLARE @etapa_nome NVARCHAR(200); DECLARE @etapa_query_sql NVARCHAR(MAX); DECLARE cur_etapa CURSOR LOCAL FAST_FORWARD FOR SELECT e.etapa_id, e.etapa_ordem, e.etapa_nome, e.etapa_query_sql FROM dbo.tb_pbi_mon_etapas e WITH (NOLOCK) WHERE e.fluxo_id = @v_fluxo_id ORDER BY e.etapa_ordem; OPEN cur_etapa; FETCH NEXT FROM cur_etapa INTO @etapa_id, @etapa_ordem, @etapa_nome, @etapa_query_sql; WHILE @@FETCH_STATUS = 0 BEGIN DECLARE @sql NVARCHAR(MAX) = N'SELECT @volumeOUT = COUNT_BIG(*) FROM ( ' + @etapa_query_sql + N' ) src;'; DECLARE @volume BIGINT; EXEC sp_executesql @sql, N'@data_inicio DATE, @data_fim DATE, @id_transportadora INT, @volumeOUT BIGINT OUTPUT', @data_inicio = @cliente_data_inicio, @data_fim = @cliente_data_fim, @id_transportadora = @cliente_id_transp, @volumeOUT = @volume OUTPUT; INSERT INTO #Resultado (cli_cd_codigo_cliente, id_transportadora, nm_transportadora, alerta_fato_id, dt_referencia, fluxo_id, fluxo_codigo, fluxo_nome, etapa_id, etapa_ordem, etapa_nome, volume, data_inicio, data_fim) VALUES (@cliente_cli_cd, @cliente_id_transp, @cliente_nm, @cliente_alerta_id, NULL, @v_fluxo_id, @v_fluxo_codigo, @v_fluxo_nome, @etapa_id, @etapa_ordem, @etapa_nome, @volume, @cliente_data_inicio, @cliente_data_fim); FETCH NEXT FROM cur_etapa INTO @etapa_id, @etapa_ordem, @etapa_nome, @etapa_query_sql; END CLOSE cur_etapa; DEALLOCATE cur_etapa; FETCH NEXT FROM cur_cli INTO @cliente_cli_cd, @cliente_id_transp, @cliente_nm, @cliente_alerta_id; END CLOSE cur_cli; DEALLOCATE cur_cli; SELECT cli_cd_codigo_cliente, id_transportadora, nm_transportadora, alerta_fato_id, dt_referencia, fluxo_id, fluxo_codigo, fluxo_nome, etapa_id, etapa_ordem, etapa_nome, volume, data_inicio, data_fim FROM #Resultado ORDER BY cli_cd_codigo_cliente, etapa_ordem; END
GO
